// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(address from, address to, uint256 id) public {
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        vm.assume(id != type(uint256).max);

        // id must be unminted before the call
        bool mintedBefore;
        try c.ownerOf(id) { mintedBefore = true; } catch { mintedBefore = false; }
        if (mintedBefore) return;

        // drive c through transferFrom; from is not the owner (id is unminted)
        vm.prank(from);
        try c.transferFrom(from, to, id) {} catch {}

        // rule: an unminted token id stays unminted after any transferFrom attempt
        bool unmintedAfter;
        try c.ownerOf(id) { unmintedAfter = false; } catch { unmintedAfter = true; }
        assertTrue(unmintedAfter);
    }
}
